{
  "decision_type": "action",
  "hypotheses": [
    {
      "id": "H1",
      "claim": "The model exploits trial-specific signatures (e.g., task direction) that transfer to new trials within the same subject/session.",
      "mechanism": "Task-level information shared across windows of a single trial allows generalization from training windows to test windows on unseen trials, driving high window split performance but low trial split performance.",
      "supporting_evidence_ids": ["obs_1", "req_2"],
      "limitations": "Does not account for subject-specific identity effects or domain shifts."
    },
    {
      "id": "H3",
      "claim": "The model exploits session identities (session-level collection effects) rather than trial content.",
      "mechanism": "Labels are correlated with unseen metadata features of the test sessions, causing high performance when those entities overlap between train and test sets but failing on truly disjoint ones. This explains why window split is high (sessions overlap) while subject split drops significantly (fewer subjects in test).",
      "supporting_evidence_ids": ["obs_1", "req_2"],
      "limitations": "Cannot distinguish from trial-specific effects without permutation tests."
    }
  ],
  "request_id": "req_3",
  "tool_id": "trial_random_labels",
  "parameters": {},
  "distinguishes": ["H1", "H3"],
  "prediction": {
    "scoring_status": "numeric",
    "metric_key": "trial_random_trial_ba_mean",
    "primary_direction": "near_zero",
    "threshold": 0.05,
    "check_facts": [],
    "conditional_predictions": [
      {"hypothesis_id": "H1", "direction": "positive", "rationale": "If trial content drives performance, randomizing labels at the trial level should break any task mapping for each new label assignment, reducing BA to chance."},
      {"hypothesis_id": "H3", "direction": "negative", "rationale": "If session identity effects drive performance, permuting labels within trials while preserving counts might still allow some leakage if metadata correlates with class; however, the primary expectation for H1 is a drop in BA."}
    ],
    "update_rule_if_opposite": "If trial_random_trial_ba_mean remains high (>0.5), this suggests session identity effects (H3) or that randomization does not break the underlying signal sufficiently to distinguish from content-based transfer."
  },
  "reasoning_summary": "Randomize labels at trial level to test if performance relies on subject/session identities vs trial-level task mapping. Expect BA drop near chance for H1, stable high BA for session effects (H3)."
}

